import {createArtworkBank} from './map4-image-bank.mjs';
// Shared completed Map2 / Map3 atlases; preload both before Map4 begins.
const bank=createArtworkBank(new URL('../assets/map4-city-details-v3/',import.meta.url),actor=>'npc-'+actor+'.png'),load=bank.load;
export function cityNPCStatus(){return bank.status(['leroy','bear']);}
export const retryCityNPCs=bank.retry;
export function drawCityNPC(r,n,x){const im=load(n.actor);if(!im)return false;const c=r.c,frame=r.reduced?0:Math.floor(r.clock*2)%2;c.save();c.imageSmoothingEnabled=false;r.ellipse(x,n.y+1,23,3,'#10203288');c.drawImage(im,frame*64,0,64,72,Math.round(x/2)*2-64,n.y-136,128,144);c.restore();return true;}
export function cityBubbleLayout(c,n,x,canvasWidth){const width=Math.min(440,canvasWidth-32),padding=20,fontSize=18,lineHeight=28,lines=[];c.font=`${fontSize}px StudioPixel,monospace`;let line='';for(const ch of n.line){if(line&&c.measureText(line+ch).width>width-padding*2){lines.push(line);line='';}line+=ch;}if(line)lines.push(line);if(lines.length>1&&lines.at(-1).length<6){const j=lines.length-2;while(lines[j].length>2&&c.measureText(lines.at(-1)).width<c.measureText(lines[j]).width*.6){lines[j+1]=lines[j].slice(-1)+lines[j+1];lines[j]=lines[j].slice(0,-1);}if(/^[，。、！？…」]/.test(lines[j+1])){lines[j+1]=lines[j].slice(-1)+lines[j+1];lines[j]=lines[j].slice(0,-1);}}const height=58+lines.length*lineHeight,left=Math.max(16,Math.min(canvasWidth-width-16,x-width/2)),top=Math.max(100,n.y-150-height);return{left,top,width,height,fontSize,lineHeight,lines};}
export function drawCityBubble(r,n,x){const c=r.c,b=cityBubbleLayout(c,n,x,r.canvas.width),tail=Math.max(b.left+24,Math.min(b.left+b.width-24,x));c.save();r.rect(b.left+4,b.top+4,b.width,b.height,'#0e0d13cc');r.rect(b.left,b.top,b.width,b.height,'#29272a');c.strokeStyle='#8c8174';c.lineWidth=3;c.strokeRect(b.left,b.top,b.width,b.height);r.line(b.left+2,b.top+3,b.left+b.width-2,b.top+3,'#4a4543',2);c.beginPath();c.moveTo(tail-10,b.top+b.height-1);c.lineTo(x,n.y-134);c.lineTo(tail+10,b.top+b.height-1);c.fillStyle='#29272a';c.fill();c.strokeStyle='#8c8174';c.lineWidth=2;c.stroke();r.rect(b.left+8,b.top+8,4,4,'#b6a68a');c.textAlign='left';c.fillStyle='#c3b7aa';c.font='12px StudioPixel,monospace';c.fillText(n.name,b.left+20,b.top+25);r.line(b.left+20,b.top+35,b.left+b.width-20,b.top+35,'#8c8174',1);c.font=`${b.fontSize}px StudioPixel,monospace`;c.fillStyle='#f0e3c8';b.lines.forEach((s,i)=>c.fillText(s,b.left+20,b.top+62+i*b.lineHeight));c.restore();return b;}
